import React, { useState, useEffect, useRef } from "react";
import "./App.css";
import botIcon from "./bot-icon.png";
import Navbar from "./components/Navbar";

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [activePage, setActivePage] = useState("chat");
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = async () => {
    if (input.trim() === "") return;

    setMessages([...messages, { text: input, type: "user" }]);
    setInput("");

    try {
      const response = await fetch("http://localhost:5000/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt: input }),
      });

      const data = await response.json();

      if (response.ok) {
        setMessages((prevMessages) => [
          ...prevMessages,
          { text: data.response, type: "bot" },
        ]);
      } else {
        throw new Error(data.error || "AI response failed");
      }
    } catch (error) {
      console.error("Error fetching response:", error);
      setMessages((prevMessages) => [
        ...prevMessages,
        { text: "⚠️ AI is not responding. Try again later.", type: "bot" },
      ]);
    }
  };

  return (
    <div className="app-container">
      <Navbar setActivePage={setActivePage} />

      <div className="content">
        {activePage === "chat" && (
          <div className="chatbox">
            <div className="messages">
              {messages.map((msg, index) => (
                <div key={index} className={`message-container ${msg.type}`}>
                  {msg.type === "bot" && <img src={botIcon} alt="Bot" className="bot-icon" />}
                  <div className={`message ${msg.type}`}>
                    <p>{msg.text}</p>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
            <div className="input-area">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask me anything..."
              />
              <button onClick={handleSendMessage}>➤</button>
            </div>
          </div>
        )}

        {activePage === "youtube" && (
          <div className="youtube">
            <h2>📺 YouTube Learning</h2>
            <p>Watch AI-related YouTube videos here!</p>
          </div>
        )}

        {activePage === "wikipedia" && (
          <div className="wikipedia">
            <h2>📖 Wikipedia Search</h2>
            <p>Look up AI-related articles on Wikipedia.</p>
          </div>
        )}

        {activePage === "test" && (
          <div className="test">
            <h2>📝 AI Knowledge Test</h2>
            <p>Take quizzes and tests to check your understanding.</p>
          </div>
        )}
      </div>

      <footer className="footer">
        <p>&copy; 2025 PAT  | @Indrajit002 </p>
      </footer>
    </div>
  );
};

export default App;
